DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'workspace_members' AND policyname = 'self_membership_workspace_members'
  ) THEN
    CREATE POLICY self_membership_workspace_members ON workspace_members
      FOR SELECT TO nominara_app
      USING (app.current_workspace() IS NULL
         AND user_id = app.current_actor());
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'workspaces' AND policyname = 'self_membership_workspaces'
  ) THEN
    CREATE POLICY self_membership_workspaces ON workspaces
      FOR SELECT TO nominara_app
      USING (app.current_workspace() IS NULL
